if (!isset($_SESSION['cart'])) $_SESSION['cart'] = [];
$notice = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  $action = $_POST['action'] ?? '';
  if ($action === 'add') {
    $idx = (int)($_POST['product'] ?? -1);
    if (isset($products[$idx])) $_SESSION['cart'][$idx] = min(20, (int)($_SESSION['cart'][$idx] ?? 0) + 1);
    header('Location: ?page=shop#collection'); exit;
  }
  if ($action === 'remove') { unset($_SESSION['cart'][(int)($_POST['product'] ?? -1)]); header('Location: ?page=cart'); exit; }
  if ($action === 'checkout') {
    if (!$_SESSION['cart']) { header('Location: ?page=cart'); exit; }
    $name=trim($_POST['full_name']??''); $phone=trim($_POST['phone']??''); $email=trim($_POST['email']??''); $address=trim($_POST['address']??''); $payment=$_POST['payment']??'';
    if (!$name || !$phone || !filter_var($email,FILTER_VALIDATE_EMAIL) || !$address || !in_array($payment,['Cash on delivery','E-wallet'],true)) $notice='Please complete all fields with a valid email and choose a payment method.';
    else {
      $db->beginTransaction();
      $s=$db->prepare('INSERT INTO orders(full_name,phone,email,address,payment) VALUES(?,?,?,?,?)'); $s->execute([$name,$phone,$email,$address,$payment]); $id=(int)$db->lastInsertId();
      $item=$db->prepare('INSERT INTO order_items(order_id,product,qty,price) VALUES(?,?,?,?)');
      foreach($_SESSION['cart'] as $i=>$qty) if(isset($products[$i])) $item->execute([$id,$products[$i]['name'],$qty,$products[$i]['price']]);
      $db->commit(); $_SESSION['cart']=[]; $_SESSION['last_order']=$id; header('Location: ?page=thanks'); exit;
    }
  }
  if ($action === 'status') {
    $id=(int)($_POST['id']??0); $payment=$_POST['payment_status']??'Pending'; $delivery=$_POST['delivery_status']??'Processing';
    if(in_array($payment,['Pending','Paid'],true)&&in_array($delivery,['Processing','Packed','On the way','Delivered'],true)) { $s=$db->prepare('UPDATE orders SET payment_status=?,delivery_status=? WHERE id=?'); $s->execute([$payment,$delivery,$id]); }
    header('Location: ?page=admin'); exit;
  }
}

