<?php elseif($page==='admin'): $orders=$db->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC); ?><section class="admin-page section"><div class="admin-heading"><div><div class="eyebrow">LIKHA TEAM · ORDER DESK</div><h1>Orders, <em>at a glance.</em></h1><p>Track payment and delivery progress for every customer order.</p></div><span class="admin-badge">ADMIN VIEW</span></div><div class="admin-stats"><div><span>All orders</span><b><?= count($orders) ?></b><small>Since launch</small></div><div><span>Awaiting payment</span><b><?= count(array_filter($orders,fn($o)=>$o['payment_status']==='Pending')) ?></b><small>Needs a check-in</small></div><div><span>On the way</span><b><?= count(array_filter($orders,fn($o)=>$o['delivery_status']==='On the way')) ?></b><small>Out for delivery</small></div><div><span>Delivered</span><b><?= count(array_filter($orders,fn($o)=>$o['delivery_status']==='Delivered')) ?></b><small>Happy arrivals</small></div></div><div class="admin-table-wrap"><div class="table-title"><h2>Recent orders</h2><span><?= count($orders) ?> total</span></div><?php if(!$orders): ?><div class="admin-empty"><span>✿</span><h3>No orders just yet</h3><p>New customer orders will show up here automatically.</p><a class="text-link" href="?page=shop#collection">Preview the shop →</a></div><?php else: ?><table class="orders-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>ITEMS</th><th>PAYMENT</th><th>DELIVERY</th><th>UPDATE STATUS</th></tr></thead><tbody><?php foreach($orders as $o): $items=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$o['id']]);$rows=$items->fetchAll(PDO::FETCH_ASSOC); ?><tr><td><b>#<?= $o['id'] ?></b><small><?= htmlspecialchars($o['created_at']) ?></small></td><td><b><?= htmlspecialchars($o['full_name']) ?></b><small><?= htmlspecialchars($o['phone']) ?> · <?= htmlspecialchars($o['email']) ?></small><small><?= htmlspecialchars($o['address']) ?></small></td><td><?php foreach($rows as $r): ?><div><?= htmlspecialchars($r['product']) ?> <small>×<?= $r['qty'] ?></small></div><?php endforeach; ?><b class="line-total"><?= peso(array_sum(array_map(fn($r)=>$r['qty']*$r['price'],$rows))) ?></b></td><td><span class="status <?= strtolower($o['payment_status']) ?>"><?= htmlspecialchars($o['payment_status']) ?></span><small><?= htmlspecialchars($o['payment']) ?></small></td><td><span class="status delivery"><?= htmlspecialchars($o['delivery_status']) ?></span></td><td><form method="post" class="status-form"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="payment_status"><option <?= $o['payment_status']==='Pending'?'selected':'' ?>>Pending</option><option <?= $o['payment_status']==='Paid'?'selected':'' ?>>Paid</option></select><select name="delivery_status"><?php foreach(['Processing','Packed','On the way','Delivered'] as $s): ?><option <?= $o['delivery_status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button>Save update</button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div><p class="admin-footnote">This demo admin page is open for presentation. Add authentication before using it with real customer information.</p></section>
